<script setup>
import {payoutTierLabel} from '../core/winning-display.js';
import {computed,ref,watch} from 'vue';
import {formatMoney as money,MARKETS,pad,today} from '../core/rules.js';
import DrawComparison from './DrawComparison.vue';
import DrawBalls from './DrawBalls.vue';
import PlayOverview from './PlayOverview.vue';
const props=defineProps({overview:Object,busy:Boolean,error:String,mode:String,drawDate:String,selection:Object,verification:Object,draws:Object,loaded:Object});
defineEmits(['refresh','sync','mode','select','adopt','open','locate','settings','source']);
const localDate=ref(props.drawDate),showSources=ref(false),selected=ref(''),page=ref(1),perspective=ref('plays');
watch(()=>props.drawDate,v=>localDate.value=v);watch(selected,()=>page.value=1);
const wins=computed(()=>(props.overview?.wins||[]).filter(e=>!selected.value||e.fileId===selected.value));
const pages=computed(()=>Math.max(1,Math.ceil(wins.value.length/30)));
watch(pages,v=>page.value=Math.min(page.value,v));
const balance=r=>r.netCents===null?'待结算':r.status==='empty'?'空账目':`${r.status==='trial'?'试算 · ':''}${r.netCents>0?'赢 +':r.netCents<0?'输 −':'持平 '}${money(Math.abs(r.netCents))}`;
</script>
<template>
 <div class="page-body ledger-overview" aria-label="全部账目统计">
  <section class="page-heading"><div><div class="eyebrow">ALL LEDGERS</div><h1>全部账目统计</h1><p>汇总左侧所有账目的当前原文，查看投注、中奖与应付。</p></div><button class="button" :disabled="busy" @click="$emit('refresh')">{{busy?'更新中…':'刷新统计'}}</button></section>
  <div class="overview-controls"><button :class="['button',{primary:mode==='latest'}]" :disabled="busy" @click="$emit('mode','latest')">各市场最近开奖</button><label>开奖日期<input v-model="localDate" type="date" :max="today()" :disabled="busy" aria-label="全部账目开奖日期" @change="$emit('mode','date',localDate)" /></label><button class="button" :disabled="busy" @click="$emit('sync')">获取最新开奖</button><button class="text-button" @click="$emit('settings')">赔率／开奖设置 ↗</button></div>
  <p class="overview-note">{{mode==='latest'?'使用各市场最近已获取的一期。':'使用所选开奖日期。'}}原文选号仍按各账目的业务日期展开；不同业务日期的账目也包含在此汇总中。</p>
  <p v-if="error" class="overview-notice" role="alert">{{error}}</p>
  <template v-if="overview">
   <div class="overview-perspective" role="group" aria-label="统计视角"><button :class="{active:perspective==='plays'}" @click="perspective='plays'">玩法视角</button><button :class="{active:perspective==='ledgers'}" @click="perspective='ledgers'">账目视角</button></div>
   <div v-if="perspective==='plays'" class="overview-global-strip"><span>全部 {{overview.rows.length}} 份账目</span><span>投注 <strong>¥ {{money(overview.stakeCents)}}</strong></span><span>{{overview.status==='pending'?'已算应付':overview.status==='trial'?'应付（试算）':'应付'}} <strong>¥ {{money(overview.payableCents??overview.payoutCents)}}</strong></span><span>退水 <strong>¥ {{money(overview.rebateCents||0)}}</strong></span><span>中奖 {{overview.wins.length}} 笔</span></div>
   <section v-else class="overview-metrics"><div><small>投注合计{{overview.issueCount?'（已解析）':''}}</small><strong>¥ {{money(overview.stakeCents)}}</strong><span>{{overview.rows.length}} 份账目</span></div><div><small>中奖账目／笔数／注数</small><strong>{{overview.winningLedgers}} / {{overview.wins.length}} / {{overview.winCount}}</strong><span>中奖明细见下方</span></div><div><small>{{overview.status==='pending'?'已算应付（未完成）':overview.status==='trial'?'应付合计（试算）':'应付合计'}}</small><strong>¥ {{money(overview.payableCents??overview.payoutCents)}}</strong><span>含退水 {{money(overview.rebateCents||0)}} · 退本金 {{money(overview.refundCents)}} 元</span></div><div><small>玩家净输赢合计{{overview.status==='trial'?'（试算）':''}}</small><strong>{{overview.netCents===null?'待结算':`${overview.netCents>0?'+':''}${money(overview.netCents)}`}}</strong><span>应付金额 − 投注总额</span></div></section>
   <p v-if="overview.status==='pending'" class="overview-notice">{{overview.pendingLedgers}}份账目待结算，{{overview.issueCount}}项原文问题。已算应付是部分金额，净输赢尚未确定。</p><p v-else-if="overview.status==='trial'" class="overview-notice">部分开奖来源或赔率尚未确认，当前金额为试算。</p>
   <div v-if="perspective==='ledgers'" class="overview-markets"><span v-for="m in overview.markets" :key="m.market">{{m.market}}市场 · 投注 {{money(m.stakeCents)}} · 已算应付 {{money(m.payableCents??m.payoutCents)}}</span></div>
   <PlayOverview v-if="perspective==='plays'" :overview="overview" :verification="verification" :odds="loaded?.settings.odds" @open="id=>$emit('open',id)" @locate="item=>$emit('locate',item)" />
   <div class="overview-draws"><div class="overview-draw-grid"><div v-for="m in MARKETS" :key="m" class="overview-draw"><div class="overview-draw-heading"><strong>{{m}}市场</strong><span v-if="draws[m]">{{draws[m].date}} · {{draws[m].issue}}期</span></div><DrawBalls v-if="draws[m]" :numbers="draws[m].numbers" :date="draws[m].date" compact /><span v-else>尚无可采用的开奖</span></div></div><button class="text-button" @click="showSources=!showSources">{{showSources?'收起开奖依据':'核对／选择开奖依据'}} ▾</button></div>
   <div v-if="showSources&&loaded"><template v-for="m in MARKETS" :key="m"><label class="overview-source">{{m}}市场<select :value="selection?.drawIds[m]||''" :aria-label="'汇总'+m+'市场开奖'" :disabled="busy" @change="$emit('select',m,$event.target.value)"><option value="">请选择开奖</option><option v-for="d in selection?.choices[m]||[]" :key="d.id" :value="d.id">{{d.date}} · {{d.issue}} · {{d.numbers.map(pad).join(' ')}} · {{d.sourceName}}</option></select></label><DrawComparison :comparison="verification[m]" :busy="busy" @adopt="id=>$emit('adopt',m,id)" @open="id=>$emit('source',id)" /></template></div>
   <section v-if="perspective==='ledgers'" class="panel overview-table"><h2>每份账目 · 玩家视角</h2><div class="overview-table-scroll"><table><thead><tr><th>账目</th><th>投注</th><th>中奖笔／注</th><th>退水</th><th>应付</th><th>净输赢</th></tr></thead><tbody><tr v-for="r in [...overview.rows].sort((a,b)=>b.stakeCents-a.stakeCents)" :key="r.id"><td><button class="text-button" @click="$emit('open',r.id)">{{r.name}} ↗</button><small>{{r.date}}</small></td><td>{{money(r.stakeCents)}}</td><td>{{r.wins.length}} / {{r.winCount}}</td><td>{{money(r.rebateCents||0)}}</td><td>{{money(r.payableCents??r.payoutCents)}}<small v-if="r.status==='pending'">部分应付</small><small v-else-if="r.status==='trial'">试算</small></td><td :class="{'profit-positive':r.netCents>0,'profit-negative':r.netCents<0}">{{balance(r)}}<small v-if="r.issues.length">{{r.issues.length}}项待处理</small></td></tr></tbody></table></div></section>
   <section v-if="perspective==='ledgers'" class="panel overview-wins"><header><h2>中奖明细</h2><select v-model="selected" aria-label="筛选中奖账目"><option value="">全部账目</option><option v-for="r in overview.rows" :key="r.id" :value="r.id">{{r.name}}</option></select></header><details v-for="e in wins.slice((page-1)*30,page*30)" :key="e.id"><summary><span>{{e.fileName}} · {{e.market}}市场 · {{e.play}}<small>中{{e.winCount}}注 · {{e.drawDate}} · {{e.issue}}期</small></span><strong>应付 {{money(e.payoutCents)}}</strong></summary><p>{{e.raw}}</p><p v-for="(t,i) in e.tiers" :key="i">{{payoutTierLabel(t)?payoutTierLabel(t)+' · ':''}}{{t.count}}注 × {{money(t.unitPayoutCents)}}元（{{t.rate}}倍）＝ {{money(t.payoutCents)}}元</p><button class="text-button" @click="$emit('locate',e)">查看原文 ↗</button></details><p v-if="!wins.length" class="overview-note">当前范围没有已算出的中奖记录。</p><div class="pagination"><span>{{wins.length}}笔</span><button :disabled="page===1" @click="page--">上一页</button>{{page}} / {{pages}}<button :disabled="page===pages" @click="page++">下一页</button></div></section>
   <p class="overview-note">应付包含按赔率计算的奖金、退本金及退水；净输赢为正表示玩家赢，为负表示玩家输。历史赔付版本单独留存，不重复累加，应付不代表已经付款。</p>
  </template><p v-else class="overview-note">{{busy?'正在读取开奖与赔率…':'暂无可用统计，请刷新。'}}</p>
 </div>
</template>
<style scoped>
.overview-global-strip{display:flex;flex-wrap:wrap;gap:10px 25px;font-size:12px;color:#718675;margin:16px 0}.overview-global-strip strong{font-size:16px;color:#315e44;margin-left:5px}
.overview-perspective{display:flex;gap:7px;margin-top:20px}.overview-perspective button{font-size:13px;padding:9px 18px;border-radius:6px;border:1px solid #dbe6dc;color:#6b826e}.overview-perspective button.active{background:#315e44;border-color:#315e44;color:white}

.ledger-overview{padding-bottom:30px}.overview-controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.overview-controls label{display:flex;gap:8px;align-items:center;font-size:12px}.overview-note{font-size:11px;color:#829078;line-height:1.9;margin:15px 0}.overview-notice{background:#fff5e8;color:#946938;font-size:12px;line-height:1.9;padding:12px;margin:14px 0;border-radius:6px}.overview-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.overview-metrics>div{background:#fff;border:1px solid #e0e7e2;border-radius:8px;padding:18px}.overview-metrics small,.overview-metrics span{display:block;color:#859278;font-size:11px}.overview-metrics strong{display:block;font-size:23px;margin:12px 0;color:#356449}.overview-markets{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:#6a8467}.overview-draws{margin:18px 0;padding:12px 16px;background:#f1f6ed;font-size:11px;line-height:1.9}.overview-draw-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(255px,1fr));gap:20px;margin-bottom:14px}.overview-draw{min-width:0}.overview-draw-heading{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:10px}.overview-draw-heading span{color:#7e8e73}.overview-source{display:grid;gap:7px;font-size:12px}.overview-source select{max-width:100%}.overview-table,.overview-wins{margin-top:20px;padding:18px}.overview-table-scroll{overflow-x:auto}.overview-table table{border-collapse:collapse;width:100%;font-size:12px;font-variant-numeric:tabular-nums;min-width:580px}.overview-table td,.overview-table th{padding:15px 10px;text-align:right;border-bottom:1px solid #edf1e8}.overview-table th{font-weight:500;color:#8a9a80}.overview-table td:first-child,.overview-table th:first-child{text-align:left}.overview-table .text-button{font-size:12px}.overview-table small{display:block;margin-top:7px;color:#93a187;font-size:10px}.overview-wins header{display:flex;justify-content:space-between;align-items:center}.overview-wins select{font-size:12px}.overview-wins details{border-bottom:1px solid #e5ebdf;font-size:12px}.overview-wins summary{display:flex;justify-content:space-between;gap:15px;padding:15px 0;cursor:pointer;line-height:1.8}.overview-wins summary small{display:block;color:#8d9d7f;font-size:10px}.overview-wins p{white-space:pre-wrap;line-height:1.9;margin:8px 0;color:#788d6e}.profit-positive{color:#b45c42}.profit-negative{color:#438064}@media(max-width:1150px){.overview-metrics{grid-template-columns:1fr 1fr}}
</style>
